import _ from 'lodash'

const dataFormatter = dataChart => {
  const dataChartFormatted = dataChart.data ? JSON.parse(dataChart.data) : {}
  if (Object.values(dataChart).length > 0) {
    if (Object.values(dataChartFormatted).length === 0) {
      return []
    }
    for (const key in dataChartFormatted) {
      const repProductName = key.replace(/-/g, '_')
      for (let i = 0; i < dataChartFormatted[key].length; i++) {
        dataChartFormatted[key][i].name = dataChartFormatted[key][i].date
        dataChartFormatted[key][i][repProductName] =
          dataChartFormatted[key][i].policy_created
        delete dataChartFormatted[key][i].policy_created
        delete dataChartFormatted[key][i].date
      }
    }
  }
  const output = []
  for (const key in dataChartFormatted) {
    dataChartFormatted[key].forEach(value => {
      output.push(value)
    })
  }
  const chartData = _(output)
    .groupBy('name')
    .map(_.spread(_.assign))
    .value()
  return _.sortBy(chartData, ['name'])
}

export default dataFormatter
