import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { Table, Input, Button, Icon } from 'antd'
import Highlighter from 'react-highlight-words'
class DashboardTable extends Component {
  state = {
    searchText: '',
    searchedColumn: '',
    dashBoardColumns: []
  }

  static propTypes = {
    data: PropTypes.object
  }

  componentDidMount () {
    this.updateDashboardTable(this.props)
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    if (nextProps.dashboardView !== this.props.dashboardView) {
      this.updateDashboardTable(nextProps)
    }
  }

  combinedTable = (claimsData, dashboardView, policyData) => {
    const { TotalTransactionValue } = dashboardView
    const { data } = claimsData
    const newData = []
    const claimsDataSource = {}

    if (data?.length > 0) {
      data.forEach((item, index) => {
        const key = item.partners || item.products
        const ratio = ((parseInt(item.claim_amount) / TotalTransactionValue) * 100).toFixed(2)
        claimsDataSource[key] = { total_settled_claims: item.total_settled_claims, claimsAmount: Number(item.claim_amount), claimsRatio: ratio }
      })
    }
    policyData.forEach(item => {
      const key = item.partner_key || item.product_key
      if (Object.prototype.hasOwnProperty.call(claimsDataSource, key)) {
        const combinedObj = { ...item, ...claimsDataSource[key] }
        if (combinedObj?.ProductDisplayName?.length === 0) {
          combinedObj.ProductDisplayName = combinedObj?.product_key?.length > 0 ? combinedObj.product_key : ''
        }
        newData.push(combinedObj)
      } else {
        item.claimsAmount = 0
        item.total_settled_claims = 0
        if (item?.ProductDisplayName?.length === 0) {
          item.ProductDisplayName = item?.product_key?.length > 0 ? item.product_key : ''
        }
        newData.push(item)
      }
    })
    return newData
  }

  updateDashboardTable = ({ dashboardView }) => {
    const { PartnerWiseCount } = dashboardView
    const tableView = Array.isArray(PartnerWiseCount) ? 'partner' : 'product'
    const dashBoardColumns = [
      {
        title: tableView === 'product' ? 'Product ID' : 'Partner',
        dataIndex: tableView === 'product' ? 'ProductDisplayName' : 'partner_key',
        key: tableView === 'product' ? 'ProductDisplayName' : 'partner_key',
        defaultSortOrder: 'ascend',
        className: 'partner-product',
        sorter: (a, b) => {
          const aKey = tableView === 'product' ? 'ProductDisplayName' : 'partner_key'
          const bKey = aKey
          return a[aKey].localeCompare(b[bKey])
        },
        ...this.getColumnSearchProps(tableView === 'product' ? 'ProductDisplayName' : 'partner_key')
      },
      {
        title: 'GWP',
        dataIndex: 'paymentSum',
        key: 'paymentSum',
        defaultSortOrder: 'ascend',
        className: 'gwp',
        sorter: (a, b) => {
          if (parseInt(a.paymentSum) < parseInt(b.paymentSum)) {
            return -1
          }
          if (parseInt(a.paymentSum) > parseInt(b.paymentSum)) {
            return 1
          }
          return 0
        },
        ...this.getColumnSearchProps('paymentSum'),
        render: (val) => val ? (new Intl.NumberFormat().format(Number.isInteger(Number(val)) ? parseInt(val) : parseFloat(val))) : ''
      },
      {
        title: 'Total Completed State Policies',
        dataIndex: 'policiesCount',
        key: 'policiesCount',
        defaultSortOrder: 'ascend',
        className: 'policiesCount',
        sorter: (a, b) => parseInt(a.policiesCount, 10) - parseInt(b.policiesCount, 10),
        ...this.getColumnSearchProps('policiesCount'),
        render: (val) => val ? (new Intl.NumberFormat().format(Number.isInteger(Number(val)) ? parseInt(val) : parseFloat(val))) : 0
      },
      {
        title: 'Total Settled Claims',
        dataIndex: 'total_settled_claims',
        key: 'total_settled_claims',
        defaultSortOrder: 'descend',
        className: 'total_settled_claims',
        sorter: (a, b) => a.total_settled_claims - b.total_settled_claims,
        render: (val) => val ? (new Intl.NumberFormat().format(Number.isInteger(Number(val)) ? parseInt(val) : parseFloat(val))) : 0
      },
      {
        title: 'Claims Amount',
        dataIndex: 'claimsAmount',
        key: 'claimsAmount',
        defaultSortOrder: 'descend',
        className: 'claimsAmount',
        sorter: (a, b) => a.claimsAmount - b.claimsAmount,
        render: (val) => val ? (new Intl.NumberFormat().format(Number.isInteger(Number(val)) ? parseInt(val) : parseFloat(val))) : ''
      }
      // {
      //   title: 'Claims Ratio',
      //   dataIndex: 'claimsRatio',
      //   key: 'claimsRatio',
      //   defaultSortOrder: 'descend',
      //   className:'claimsRatio',
      //   sorter: (a, b) => a.claimsRatio - b.claimsRatio
      // }
    ]

    this.setState({
      dashBoardColumns
    })
  }

  getColumnSearchProps = dataIndex => ({
    filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters }) => (
      <div style={{ padding: 8 }}>
        <Input
          ref={node => {
            this.searchInput = node
          }}
          placeholder={`Search ${dataIndex}`}
          value={selectedKeys?.[0]}
          onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
          onPressEnter={() => this.handleSearch(selectedKeys, confirm, dataIndex)}
          style={{ width: 188, marginBottom: 8, display: 'block' }}
        />
        <Button
          type='primary'
          onClick={() => this.handleSearch(selectedKeys, confirm, dataIndex)}
          icon='search'
          size='small'
          style={{ width: 90, marginRight: 8 }}
        >
          Search
        </Button>
        <Button onClick={() => this.handleReset(clearFilters)} size='small' style={{ width: 90 }}>
          Reset
        </Button>
      </div>
    ),
    filterIcon: filtered => (
      <Icon type='search' style={{ color: filtered ? '#1890ff' : undefined }} />
    ),
    onFilter: (value, record) =>
      record[dataIndex]
        .toString()
        .toLowerCase()
        .includes(value.toLowerCase()),
    onFilterDropdownVisibleChange: visible => {
      if (visible) {
        setTimeout(() => this.searchInput.select())
      }
    },
    render: text =>
      this.state.searchedColumn === dataIndex
        ? <Highlighter
            highlightStyle={{ backgroundColor: '#ffc069', padding: 0 }}
            searchWords={[this.state.searchText]}
            autoEscape
            textToHighlight={text.toString()}
          />
        : (
            text
          )
  });

  handleSearch = (selectedKeys, confirm, dataIndex) => {
    confirm()
    this.setState({
      searchText: selectedKeys[0],
      searchedColumn: dataIndex
    })
  };

  handleReset = clearFilters => {
    clearFilters()
    this.setState({ searchText: '' })
  };

  render () {
    const { policyDashboardTable: policyData, claimsDashboardTable: claimsData, dashboardView } = this.props
    const tableData = this.combinedTable(claimsData, dashboardView, policyData)
    const { dashBoardColumns } = this.state
    return (
      <Table
        columns={dashBoardColumns}
        dataSource={tableData}
        bordered
      />
    )
  }
}

export default DashboardTable
