import React, { Component } from 'react'
import { Row, Col } from 'antd'
import moment from 'moment'
class CustomToolTipNotification extends Component {
  render () {
    const { active, payload, label } = this.props
    var newLabel = moment(label).format('DD MMMM YYYY')
    if (active) {
      return (
        <div style={{ borderRadius: 10, width: 500, height: 'auto', backgroundColor: '#fff' }}>
          <div style={{ height: 20, display: 'flex', justifyContent: 'center', alignItems: 'center', color: '#000', fontSize: 9, fontWeight: 800, width: '100%', borderTopLeftRadius: 10, borderTopRightRadius: 10 }}>
            {newLabel}
          </div>
          <Row>
            {
              payload &&
              payload.map((item, index) => {
                return (
                  <Col span={12} style={{ marginTop: 5 }} key={index}>
                    <div style={{ color: `${item.stroke}`, display: '-webkit-inline-box', marginLeft: 10, marginRight: 10 }}>{item.name}</div>
                    <span style={{ display: 'webkit-inline-box' }}>
                      {
                        new Intl.NumberFormat().format(item.value)
                      }
                    </span>
                  </Col>
                )
              })
            }
          </Row>
        </div>
      )
    }
    return null
  }
}
export default CustomToolTipNotification
