import React, { Component } from 'react'
import PropTypes from 'prop-types'
import moment from 'moment'
import DashBoardFilterStyle from './index.style'
import { Row, Col, DatePicker, Select, Button, Checkbox } from 'antd'
import PermissionChecker from '../../../../components/permissionChecker'

class DashboardFilterHeader extends Component {
  static propTypes = {
    data: PropTypes.object,
    permissions: PropTypes.array,
    partners: PropTypes.array,
    products: PropTypes.array,
    getProducts: PropTypes.func,
    getPolicyListDashboard: PropTypes.func
  }

  constructor(props) {
    super(props)
    this.state = {
      startDate: moment().subtract(1, 'week').format('YYYY-MM-DD'),
      endDate: moment().format('YYYY-MM-DD'),
      productKey: undefined,
      excludeGopassengerData: true,
      excludePartnerKeys: '',
      partner: '',
      loading: false,
      selectedPartners: [],
      selectedProducts: []
    }
  }

  onChangePartner = (partners) => {
    // partner is a list of string as selected partner from the drop down
    if (this.state.selectedProducts.length) {
      // clear filter if any product selected
      this.setState({
        selectedProducts: []
      })
    }
    this.setState({ selectedPartners: partners, partner: partners && partners.toString(), productKey: undefined })
    this.props.getProducts({ query: { partner_code: partners } })
  }

  onChangeProduct = (products) => {
    this.setState({ selectedProducts: products, productKey: products.toString() })
  }

  onChangeDateStart = (date, dateString) => {
    this.setState({ startDate: dateString })
  }

  onChangeDateEnd = (date, dateString) => {
    this.setState({ endDate: dateString })
  }

  resetFilter = () => {
    this.setState({
      startDate: moment().subtract(1, 'week').format('YYYY-MM-DD'),
      endDate: moment().format('YYYY-MM-DD'),
      productKey: undefined,
      excludeGopassengerData: true,
      excludePartnerKeys: '',
      partner: '',
      loading: false,
      selectedPartners: [],
      selectedProducts: []
    }, () => {
        const { excludeGopassengerData } = this.state
        const data = {
        startDate: moment().subtract(1, 'week').format('YYYY-MM-DD'),
        endDate: moment().format('YYYY-MM-DD'),
        productKey: undefined,
        partner: '',
        excludePartnerKeys: excludeGopassengerData ? 'gopassenger' : '',
        excludeProductKeys: '',
        dashboardView: 'partner'
      }
      this.props.getPolicyListDashboard(data)
    })
    
  }

  submitChart = () => {
    const {
      startDate, endDate, productKey, partner, excludeGopassengerData
    } = this.state

    const data = {
      startDate,
      endDate,
      productKey,
      partner,
      excludePartnerKeys: excludeGopassengerData ? 'gopassenger' : '',
      excludeProductKeys: '',
      dashboardView: (productKey !== undefined || partner) ? 'product' : 'partner'
    }
    this.props.getPolicyListDashboard(data)
  }

  handleGopassengerExclude = () => {
    this.setState({
      excludeGopassengerData: !this.state.excludeGopassengerData
    }, () => this.submitChart())
  }

  disabledStartDate = startDate => {
    const { endDate } = this.state
    if (!startDate || !endDate) {
      return false
    }
    return startDate.valueOf() > moment(endDate).valueOf()
  }

  disabledEndDate = endDate => {
    const { startDate } = this.state
    if (!endDate || !startDate) {
      return false
    }
    return endDate.valueOf() <= moment(startDate).valueOf() - 1
  }

  render() {
    const {
      permissions,
      products = [],
      partners = []
    } = this.props
    const { excludeGopassengerData, selectedPartners, selectedProducts, startDate, endDate } = this.state
    return (
      <DashBoardFilterStyle>
        <Row type='flex'>
          <Col sm={4}>
            <div className='date-container'>
              <span>From</span>
              <DatePicker
                defaultValue={moment(startDate)}
                value={moment(startDate)}
                format='YYYY-MM-DD'
                placeholder='Start Date'
                disabledDate={this.disabledStartDate}
                onChange={this.onChangeDateStart}
              />
            </div>
          </Col>
          <Col sm={4}>
            <div className='date-container'>
              <span>To</span>
              <DatePicker
                defaultValue={moment(endDate)}
                value={moment(endDate)}
                format='YYYY-MM-DD'
                placeholder='End Date'
                disabledDate={this.disabledEndDate}
                onChange={this.onChangeDateEnd}
              />
            </div>
          </Col>
          <Col className='filter-select-option' sm={4}>
            <Select
              showSearch
              dropdownMatchSelectWidth={false}
              placeholder='Select Partner'
              optionFilterProp='children'
              value={selectedPartners}
              allowClear
              onChange={this.onChangePartner}
              filterOption={(input, option) =>
                option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
            >
              {
                partners.map((partner) =>
                  <Select.Option value={partner.code} key={partner.code}>
                    {partner.name}
                  </Select.Option>
                )
              }
            </Select>
          </Col>
          <Col className='filter-select-option' sm={4}>
            <PermissionChecker permissionSetter='ops.policy_select_products' permissionGetter={permissions}>
              <Select
                showSearch
                disabled={!(selectedPartners && selectedPartners.length > 0)}
                mode='multiple'
                dropdownMatchSelectWidth={false}
                placeholder='Select Product'
                optionFilterProp='children'
                value={selectedProducts}
                onChange={this.onChangeProduct}
                filterOption={(input, option) =>
                  option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
              >
                {
                  products.map((product, index) =>
                    <Select.Option value={product.name} key={`product_${index + 1}`}>
                      {product.display_name}
                    </Select.Option>
                  )
                }
              </Select>
            </PermissionChecker>
          </Col>
          <Col className='filter-btn' lg={3} xs={12} md={3}>
            <Button
              type='primary'
              loading={this.state.loading}
              onClick={this.submitChart}
            >
              {this.state.loading ? 'Please wait ...' : 'Submit'}
            </Button>
          </Col>
          <Col className='filter-btn' lg={3} xs={12} md={3}>
            <Button
              type='default'
              onClick={this.resetFilter}
            >
              Clear Filter
            </Button>
          </Col>
          <Col className='dashboard-gopassenger-checkbox' lg={6} xs={12} md={6}>
            <Checkbox
              onClick={this.handleGopassengerExclude}
              checked={excludeGopassengerData}
            >
              Exclude Gopassenger Data
            </Checkbox>
          </Col>
        </Row>
      </DashBoardFilterStyle>
    )
  }
}

export default DashboardFilterHeader
