import React, { Component } from 'react'
import PropTypes from 'prop-types'
import _ from 'lodash'
import {
  LineChart, XAxis, YAxis, Tooltip, CartesianGrid,
  Legend, Line, Surface, Symbols, ResponsiveContainer
} from 'recharts'
import chartDataFormatter from '../../../../../helpers/chartDataFormatter'
import CustomTooltip from '../customTooltip'
import { getRandomColor } from '../../../../../helpers/utility'
import { LegendContentStyle } from './index.style'

class StackedLineChart extends Component {
  static propTypes = {
    policyList: PropTypes.array,
    products: PropTypes.array,
    chartData: PropTypes.array,
    width: PropTypes.number,
    loaderFailedFetch: PropTypes.oneOfType([
      PropTypes.func,
      PropTypes.bool
    ])
  }

  constructor (props) {
    super(props)
    this.state = {
      disabledLegend: [],
      policyListLineColors: []
    }
  }

  componentDidMount () {
    const { policyList } = this.props
    this.updatePolicyListColor(policyList)
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { policyList } = nextProps
    this.updatePolicyListColor(policyList)
  }

  updatePolicyListColor = (policyList) => {
    const policyListLineColors = policyList.map(item => ({
      color: getRandomColor(),
      keyName: item
    }))
    this.setState({
      policyListLineColors,
      disabledLegend: [] // this is reset the legends
    })
  }

  handleLegendClick = (dataKey) => {
    if (_.includes(this.state.disabledLegend, dataKey)) {
      this.setState({
        disabledLegend: this.state.disabledLegend.filter(obj => obj !== dataKey)
      })
    } else {
      this.setState({ disabledLegend: this.state.disabledLegend.concat(dataKey) })
    }
  }

  getChartConfig = (data = []) => {
    return {
      componentName: 'StackedAreaChart',
      key: 'StackedAreaChart',
      title: 'Stacked Area Chart',
      width: 350,
      height: 350,
      datas: data
    }
  }

  renderChart = (products = []) => {
    return products.filter(
      item => !_.includes(this.state.disabledLegend, item.keyName)
    ).map((value, index) => {
      return (
        <Line
          key={index}
          type='linear'
          dataKey={value.keyName && value.keyName.replace(/-/g, '_')}
          stackId='1'
          stroke={value.color}
          strokeWidth={2}
        />
      )
    })
  }

  renderLegends = (props) => {
    const { payload } = props
    return (
      <LegendContentStyle>
        {payload.map(entry => {
          const { dataKey, color } = entry
          const active = _.includes(this.state.disabledLegend, dataKey)
          const style = {
            color: active ? '#AAA' : '#000'
          }
          return (
            <span
              key={dataKey}
              className='legend-item'
              onClick={() => this.handleLegendClick(dataKey)}
              style={style}
            >
              <Surface width={10} height={10}>
                <Symbols cx={5} cy={5} type='circle' size={50} fill={color} />
                {active && (
                  <Symbols
                    cx={5}
                    cy={5}
                    type='circle'
                    size={25}
                    fill='#FFF'
                  />
                )}
              </Surface>
              &nbsp;
              <span>{dataKey}</span>
            </span>
          )
        })}
      </LegendContentStyle>
    )
  }

  dataFormater = (number) => {
    if (number > 1000000000) {
      return (number / 1000000000).toString() + 'B'
    } else if (number > 1000000) {
      return (number / 1000000).toString() + 'M'
    } else if (number > 1000) {
      return (number / 1000).toString() + 'K'
    } else {
      return number.toString()
    }
  }

  render () {
    const { chartData, width } = this.props
    const response = chartDataFormatter(chartData)
    const chartConfiguration = this.getChartConfig(response)
    const stackConfig = {
      ...chartConfiguration,
      width: width || (window.innerWidth < 450 ? 300 : 1100)
    }
    const { policyListLineColors } = this.state
    return (
      <ResponsiveContainer
        width={stackConfig.width}
        height={stackConfig.height}
      >
        <LineChart
          data={stackConfig.datas}
          margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
        >
          <CartesianGrid strokeDasharray='3 3' />
          <XAxis dataKey='name' />
          <YAxis minTickGap={6} allowDataOverflow tickFormatter={this.dataFormater} />
          <Tooltip content={<CustomTooltip />} />
          <Legend
            payload={policyListLineColors.map((val, key) => ({
              dataKey: val.keyName,
              color: val.color
            }))}
            content={this.renderLegends}
          />
          {
            policyListLineColors.length ? this.renderChart(policyListLineColors) : (<h1>Data not found</h1>)
          }
        </LineChart>
      </ResponsiveContainer>
    )
  }
}

export default StackedLineChart
