import React, { Component } from 'react'
import PropTypes from 'prop-types'
import moment from 'moment'
import { connect } from 'react-redux'
import { Row, Col, Alert } from 'antd'
import _ from 'lodash'
import IsoWidgetBox from '../../Widgets//widget-box'
import policyDashboardActions from '../../../redux/dashboard/actions'
import insuranceAction from '../../../redux/policy/actions'
import PolicyDashboardStyle from './index.style'
import StickerWidget from '../../Widgets/sticker/sticker-widget'
import { POLICY_DASHBOARD_STICKER } from '../constants'
import CircularLoader from '../../../components/CircularLoader'
import DashboardFilterHeader from '../components/DashboardFilterHeader'
import StackedLineChart from '../../Charts/recharts/charts/StackedLineChart'
// import DashboardPieChart from '../components/DashboardPieCart'
import DashboardTable from '../components/DashboardTable.js'

const { getPolicyListDashboard } = policyDashboardActions
const { getInsuranceData, getProducts } = insuranceAction
class PolicyDashboard extends Component {
  static propTypes = {
    permissions: PropTypes.array // this the permission for the user
  }

  constructor (props) {
    super(props)
    this.state = {
      defaultData: {
        startDate: moment().subtract(1, 'week').format('YYYY-MM-DD'),
        endDate: moment().format('YYYY-MM-DD'),
        productKey: '',
        excludeProductKeys: '',
        partner: '',
        excludePartnerKeys: 'gopassenger',
        dashboardView: 'partner'
      },
      lineChartWidth: window.innerWidth < 450 ? 300 : 1100,
      error: ''
    }
  }

  componentDidMount () {
    this.props.getPolicyListDashboard(this.state.defaultData)
    this.props.getInsuranceData()
    // this set the inner width for the line
    this.setState({
      lineChartWidth: document.getElementById('policyLineChart').offsetWidth
    })
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { policyListDashBoardLoading, policyListDashBoardError } = nextProps
    const { policyListDashboardStatus } = nextProps.policyList
    if (!policyListDashBoardLoading && policyListDashBoardError) {
      if (policyListDashboardStatus !== 'success') {
        this.setState({
          error: policyListDashboardStatus
        })
      }
    }
  }

  renderpolicyGraphData = (policyDashboardData) => {
    const mainObject = {}
    const stringyfiedData = {}
    policyDashboardData.forEach(items => {
      const key = items.ProductDisplayName !== undefined ? items.ProductDisplayName : items.partner_key
      if (Object.prototype.hasOwnProperty.call(mainObject, key)) {
        mainObject[key] = [...mainObject[key], {
          date: items.created_at,
          policy_created: items.policiesCount
        }]
      } else {
        mainObject[key] = [{ date: items.created_at, policy_created: items.policiesCount }]
      }
    })
    stringyfiedData.data = JSON.stringify(mainObject)
    return stringyfiedData
  }

  renderpolicyListData = (policyDashboardData) => {
    const array = []
    policyDashboardData.forEach(items => {
      const keys = items.ProductDisplayName !== undefined ? items.ProductDisplayName : items.partner_key
      if (!_.includes(array, keys)) {
        array.push(keys)
      }
    })
    return array
  }

  getStickerContainer = (policyData, claimsData) => {
    return (
      POLICY_DASHBOARD_STICKER.map(item => {
        let price
        if (item.id === 'TotalTransactionValue') {
          price = policyData.TotalTransactionValue && policyData.TotalTransactionValue.toFixed(2)
        } else if (item.id === 'total_claim_amount') {
          price = claimsData.total_claim_amount
        }
        const numberElm = price ? `Rp ${new Intl.NumberFormat().format(price)}` : (policyData[item.id] ? new Intl.NumberFormat().format(policyData[item.id]) : 0)

        return (
          <Col span={8} key={item.id}>
            <StickerWidget
              number={numberElm}
              text={item.displayName}
              icon={item.icon}
              fontColor={item.fontColor}
              bgColor={item.bgColor}
            />
          </Col>
        )
      })
    )
  }

  handleProductData = (data) => {
    if (!data) {
      return null
    }

    if (Array.isArray(data)) {
      data.forEach((val) => {
        if (val?.ProductDisplayName === '') {
          val.ProductDisplayName = val?.product_key
        }
      })
    }

    return data
  }

  render () {
    const { error, lineChartWidth } = this.state
    const {
      policyListDashBoardLoading,
      getPolicyListDashboard,
      getProducts,
      policyList,
      permissions,
      partners,
      products
    } = this.props
    const policyData = _.get(policyList, 'data.policyData', {})
    const claimsData = _.get(policyList, 'data.claimsData', {})
    const policyDashboardData = this.handleProductData(policyData.ProductWiseCount) || policyData.PartnerWiseCount || []

    const policyDataWithoutGrouping = policyData.ProductWiseCountWithoutDateGrouping || policyData.PartnerWiseCountWithoutDateGrouping || []
    const policyGraphData = policyDashboardData.length ? this.renderpolicyGraphData(policyDashboardData) : policyDashboardData
    const policyListData = policyDashboardData.length ? this.renderpolicyListData(policyDashboardData) : policyDashboardData

    return (
      <PolicyDashboardStyle>
        <CircularLoader isSpining={policyListDashBoardLoading}>
          {
            _.size(policyData) === 0 && (error && <Alert message={error} type='error' closeText='Close' />)
          }
          <Row gutter={{ xs: 16, sm: 16, md: 16 }}>
            {
              this.getStickerContainer(policyData, claimsData)
            }
          </Row>
          <DashboardFilterHeader
            getPolicyListDashboard={getPolicyListDashboard}
            getProducts={getProducts}
            permissions={permissions}
            partners={partners}
            products={products}
          />
          <IsoWidgetBox height={455}>
            <Row type='flex'>
              <Col xl={23} id='policyLineChart'>
                <StackedLineChart
                  products={products}
                  policyList={policyListData}
                  chartData={policyGraphData}
                  loaderFailedFetch={!!error}
                  width={lineChartWidth}
                />
              </Col>
              {/* <Col xl={10}>
                {
                  Object.keys(policyData).length > 0 &&
                  <DashboardPieChart pieChartdata={policyData} />
                }
              </Col> */}
            </Row>
          </IsoWidgetBox>
          <IsoWidgetBox className='space-top'>
            {
              Object.keys(policyData).length > 0 &&
              (
                <Row type='flex'>
                  <Col xl={23}>
                    <DashboardTable policyDashboardTable={policyDataWithoutGrouping} dashboardView={policyData} claimsDashboardTable={claimsData} />
                  </Col>
                </Row>
              )
            }
          </IsoWidgetBox>
        </CircularLoader>
      </PolicyDashboardStyle>
    )
  }
}

export default connect(
  state => ({
    policyList: state.Dashboard,
    partners: state.Insurance.partners,
    partnersPolicyData: state.Insurance.policyList,
    policyListDashBoardLoading: state.Loading.GET_POLICY_LIST_DASHBOARD,
    policyListDashBoardError: state.Error.GET_POLICY_LIST_DASHBOARD,
    products: state.Policy.products
  }),
  {
    getPolicyListDashboard,
    getInsuranceData,
    getProducts
  }
)(PolicyDashboard)
